{-| @Backend.Runtime.Host.State — what a host call leaves behind for the program to read: whether it was done, what the host said when it was not, and the run gate that lets one thread run at a time. -}
module Pudu.Backend.Runtime.Host.State (hostStateParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
hostStateParts :: [(Text, [Text], [Text])]
hostStateParts =
  [ ("host_optional", [],
      [ "/* A helper or a variable that some programs select and never reach. */"
      , "#if defined(__GNUC__) || defined(__clang__)"
      , "#define PUDU_OPTIONAL __attribute__((unused))"
      , "#else"
      , "#define PUDU_OPTIONAL"
      , "#endif"
      ])
  , ("host_status", ["host_optional", "text"],
      [ "/* What the last host call on this thread left: 0 done, 1 failed, 2 nothing"
      , "   there, 3 ended. The words are read once, by the failure that carries them. */"
      , "PUDU_OPTIONAL static _Thread_local int pudu_host_status = 0;"
      , "PUDU_OPTIONAL static _Thread_local pudu_text pudu_host_said = {(const unsigned char *)\"\", 0, NULL};"
      ])
  , ("host_state", ["host_optional", "host_status", "kernel_int"],
      [ "PUDU_OPTIONAL static inline pudu_int pudu_host_state(void) { return pudu_kernel_int(pudu_host_status); }"
      ])
  , ("host_message", ["host_optional", "host_status"],
      [ "PUDU_OPTIONAL static inline pudu_text pudu_host_message(void) {"
      , "  pudu_text said = pudu_host_said;"
      , "  pudu_host_said = (pudu_text){(const unsigned char *)\"\", 0, NULL};"
      , "  return said;"
      , "}"
      ])
  , ("host_done", ["host_optional", "host_status"],
      [ "PUDU_OPTIONAL static inline void pudu_host_done(int status) { pudu_host_status = status; }"
      ])
  , ("host_fail", ["host_optional", "host_status", "text_copy"],
      [ "PUDU_OPTIONAL static inline void pudu_host_fail(const char *message) {"
      , "  pudu_text_release(pudu_host_said);"
      , "  pudu_host_said = pudu_text_copy(message, strlen(message));"
      , "  pudu_host_status = 1;"
      , "}"
      ])
  , ("host_fail_io", ["host_optional", "host_status", "text_allocate"],
      [ "/* The kind of failure an error number is, in the interpreter's words. */"
      , "PUDU_OPTIONAL static inline const char *pudu_host_failure_kind(int code) {"
      , "  switch (code) {"
      , "    case ENOENT: case ESRCH: case ENXIO: case ECHILD: case ECONNREFUSED: case EHOSTUNREACH: case ENETUNREACH: return \"does not exist\";"
      , "    case EACCES: case EPERM: case EROFS: case EFBIG:"
      , "#ifdef EDQUOT"
      , "    case EDQUOT:"
      , "#endif"
      , "      return \"permission denied\";"
      , "    case EEXIST: case EALREADY: case EINPROGRESS: case EISCONN: return \"already exists\";"
      , "    case EISDIR: case ENOTDIR: return \"inappropriate type\";"
      , "    case EBUSY: case EADDRINUSE: case EDEADLK: case ETXTBSY: return \"resource busy\";"
      , "    case E2BIG: case EAGAIN: case EMFILE: case EMLINK: case EMSGSIZE: case ENFILE: case ENOBUFS: case ENOLCK: case ENOMEM: case ENOSPC: return \"resource exhausted\";"
      , "    case EBADF: case EDESTADDRREQ: case EDOM: case EILSEQ: case EINVAL: case ELOOP: case ENAMETOOLONG: case ENOEXEC: case ENOTCONN: case ENOTSOCK: return \"invalid argument\";"
      , "    case EINTR: return \"interrupted\";"
      , "    case EIO: return \"hardware fault\";"
      , "    case ECONNRESET: case ENETDOWN: case ENETRESET: case EPIPE: return \"resource vanished\";"
      , "    case ENOTEMPTY: return \"unsatisfied constraints\";"
      , "    case ENOTTY: return \"illegal operation\";"
      , "    case ETIMEDOUT: return \"timeout\";"
      , "    case EADDRNOTAVAIL: case EAFNOSUPPORT: case ENODEV: case ENOSYS: case ENOTSUP: case ERANGE: case ESPIPE: case EXDEV: return \"unsupported operation\";"
      , "    default: return \"failed\";"
      , "  }"
      , "}"
      , "/* A refusal worded as the interpreter's runtime words one: the path, the"
      , "   operation, the kind of failure, and the system's own reason. */"
      , "PUDU_OPTIONAL static inline void pudu_host_fail_reason(pudu_text path, const char *operation, const char *kind, const char *reason) {"
      , "  size_t named = strlen(operation), kinded = strlen(kind), reasoned = strlen(reason);"
      , "  size_t length = path.length + (path.length != 0 ? 2 : 0) + named + 2 + kinded + (reasoned != 0 ? reasoned + 3 : 0);"
      , "  unsigned char *bytes, *cursor;"
      , "  pudu_text_release(pudu_host_said);"
      , "  pudu_host_said = pudu_text_allocate(length, &bytes);"
      , "  cursor = bytes;"
      , "  if (path.length != 0) { memcpy(cursor, path.bytes, path.length); cursor += path.length; *cursor++ = ':'; *cursor++ = ' '; }"
      , "  memcpy(cursor, operation, named); cursor += named; *cursor++ = ':'; *cursor++ = ' ';"
      , "  memcpy(cursor, kind, kinded); cursor += kinded;"
      , "  if (reasoned != 0) { *cursor++ = ' '; *cursor++ = '('; memcpy(cursor, reason, reasoned); cursor += reasoned; *cursor++ = ')'; }"
      , "  pudu_host_status = 1;"
      , "}"
      , "PUDU_OPTIONAL static inline void pudu_host_fail_io(pudu_text path, const char *operation, int code) {"
      , "  pudu_host_fail_reason(path, operation, pudu_host_failure_kind(code), strerror(code));"
      , "}"
      ])
  , ("host_grow", ["host_optional", "memory_failure"],
      [ "/* Room for this many bytes, keeping what the block held. */"
      , "PUDU_OPTIONAL static inline void *pudu_host_grow(void *held, size_t bytes) {"
      , "  void *grown = held == NULL ? malloc(bytes) : realloc(held, bytes);"
      , "  if (grown == NULL) pudu_memory_failure();"
      , "  return grown;"
      , "}"
      ])
  , ("host_path", ["host_optional", "memory_failure"],
      [ "/* A path as the system reads one: its bytes and an ending zero. */"
      , "PUDU_OPTIONAL static inline char *pudu_host_path(pudu_text path) {"
      , "  char *copy = malloc(path.length + 1);"
      , "  if (copy == NULL) pudu_memory_failure();"
      , "  if (path.length != 0) memcpy(copy, path.bytes, path.length);"
      , "  copy[path.length] = 0;"
      , "  return copy;"
      , "}"
      ])
  , ("host_time", [],
      [ "#include <time.h>"
      ])
  , ("host_gate", ["host_optional", "host_time"],
      [ "#include <pthread.h>"
      , "/* One thread runs at a time. Whoever holds the serving ticket runs; a thread"
      , "   that must wait gives the ticket up and takes a new one when it may go on."
      , "   The main thread starts with ticket zero. */"
      , "PUDU_OPTIONAL static pthread_mutex_t pudu_gate_lock = PTHREAD_MUTEX_INITIALIZER;"
      , "PUDU_OPTIONAL static pthread_cond_t pudu_gate_moved = PTHREAD_COND_INITIALIZER;"
      , "PUDU_OPTIONAL static uint64_t pudu_gate_next = 1, pudu_gate_serving = 0, pudu_gate_changes = 0;"
      , "PUDU_OPTIONAL static int pudu_gate_shared = 0;"
      , "PUDU_OPTIONAL static inline void pudu_host_leave(void) {"
      , "  pthread_mutex_lock(&pudu_gate_lock);"
      , "  pudu_gate_serving += 1;"
      , "  pthread_cond_broadcast(&pudu_gate_moved);"
      , "  pthread_mutex_unlock(&pudu_gate_lock);"
      , "}"
      , "PUDU_OPTIONAL static inline void pudu_host_enter(void) {"
      , "  uint64_t ticket;"
      , "  pthread_mutex_lock(&pudu_gate_lock);"
      , "  ticket = pudu_gate_next++;"
      , "  while (pudu_gate_serving != ticket) pthread_cond_wait(&pudu_gate_moved, &pudu_gate_lock);"
      , "  pthread_mutex_unlock(&pudu_gate_lock);"
      , "}"
      , "/* Lets the threads already waiting run before this one goes on. */"
      , "PUDU_OPTIONAL static inline void pudu_host_yield(void) {"
      , "  if (pudu_gate_shared) { pudu_host_leave(); pudu_host_enter(); }"
      , "}"
      , "/* Something a waiting thread may be waiting for has changed. */"
      , "PUDU_OPTIONAL static inline void pudu_host_changed(void) {"
      , "  pthread_mutex_lock(&pudu_gate_lock);"
      , "  pudu_gate_changes += 1;"
      , "  pthread_cond_broadcast(&pudu_gate_moved);"
      , "  pthread_mutex_unlock(&pudu_gate_lock);"
      , "}"
      , "/* Lets others run until something changes or the time is up; 0 when it is up. */"
      , "PUDU_OPTIONAL static inline int pudu_host_wait(const struct timespec *until) {"
      , "  uint64_t seen, ticket;"
      , "  int moved = 1;"
      , "  pthread_mutex_lock(&pudu_gate_lock);"
      , "  seen = pudu_gate_changes;"
      , "  pudu_gate_serving += 1;"
      , "  pthread_cond_broadcast(&pudu_gate_moved);"
      , "  while (pudu_gate_changes == seen) {"
      , "    if (until == NULL) pthread_cond_wait(&pudu_gate_moved, &pudu_gate_lock);"
      , "    else if (pthread_cond_timedwait(&pudu_gate_moved, &pudu_gate_lock, until) == ETIMEDOUT) { moved = 0; break; }"
      , "  }"
      , "  ticket = pudu_gate_next++;"
      , "  while (pudu_gate_serving != ticket) pthread_cond_wait(&pudu_gate_moved, &pudu_gate_lock);"
      , "  pthread_mutex_unlock(&pudu_gate_lock);"
      , "  return moved;"
      , "}"
      , "/* The moment this many milliseconds from now, on the clock waits are timed by. */"
      , "PUDU_OPTIONAL static inline struct timespec pudu_host_until(int64_t millis) {"
      , "  struct timespec until;"
      , "  (void)clock_gettime(CLOCK_REALTIME, &until);"
      , "  until.tv_sec += (time_t)(millis / 1000);"
      , "  until.tv_nsec += (long)(millis % 1000) * 1000000L;"
      , "  if (until.tv_nsec >= 1000000000L) { until.tv_sec += 1; until.tv_nsec -= 1000000000L; }"
      , "  return until;"
      , "}"
      ])
  , ("host_objects", ["host_optional", "host_grow", "kernel_signed"],
      [ "/* Everything a token names: threads, channels, locks and cells share one"
      , "   run of numbers, as the interpreter's store hands them out. */"
      , "typedef struct { int kind; void *object; } pudu_host_object;"
      , "PUDU_OPTIONAL static pudu_host_object *pudu_host_table = NULL;"
      , "PUDU_OPTIONAL static size_t pudu_host_room = 0, pudu_host_held = 0;"
      , "PUDU_OPTIONAL static int64_t pudu_host_next_token = 1;"
      , "PUDU_OPTIONAL static inline int64_t pudu_host_register(int kind, void *object) {"
      , "  int64_t token = pudu_host_next_token++;"
      , "  if ((size_t)token >= pudu_host_room) {"
      , "    size_t room = pudu_host_room < 8 ? 8 : pudu_host_room * 2;"
      , "    pudu_host_object *table;"
      , "    while (room <= (size_t)token) room *= 2;"
      , "    table = pudu_host_grow(pudu_host_table, room * sizeof *table);"
      , "    memset(table + pudu_host_room, 0, (room - pudu_host_room) * sizeof *table);"
      , "    pudu_host_table = table;"
      , "    pudu_host_room = room;"
      , "  }"
      , "  pudu_host_table[token].kind = kind;"
      , "  pudu_host_table[token].object = object;"
      , "  pudu_host_held += 1;"
      , "  return token;"
      , "}"
      , "PUDU_OPTIONAL static inline void *pudu_host_find(int kind, pudu_int token) {"
      , "  int64_t wanted = pudu_kernel_signed(token.bits);"
      , "  if (wanted < 1 || (uint64_t)wanted >= pudu_host_room || pudu_host_table[wanted].kind != kind) return NULL;"
      , "  return pudu_host_table[wanted].object;"
      , "}"
      , "/* The table goes with its last object. */"
      , "PUDU_OPTIONAL static inline void pudu_host_forget(pudu_int token) {"
      , "  pudu_host_table[pudu_kernel_signed(token.bits)].kind = 0;"
      , "  pudu_host_held -= 1;"
      , "  if (pudu_host_held == 0) { free(pudu_host_table); pudu_host_table = NULL; pudu_host_room = 0; }"
      , "}"
      ])
  ]
